<?php
$base='../'; $tituloPagina='Administrar productos'; require_once __DIR__ . '/../php/conexion.php'; require_once __DIR__ . '/../php/auth.php'; require_once __DIR__ . '/../php/util.php'; requerirAdministrador();
if(isset($_GET['eliminar'])) { $id=(int)$_GET['eliminar']; $stmt=$conexion->prepare('DELETE FROM productos WHERE id_producto=?'); $stmt->bind_param('i',$id); if($stmt->execute()) mensaje('success','Producto eliminado.'); else mensaje('danger','No se puede eliminar un producto que pertenece a una venta.'); header('Location: productos.php');exit; }
$productos=$conexion->query('SELECT p.*,c.nombre_categoria FROM productos p JOIN categorias c ON c.id_categoria=p.id_categoria ORDER BY p.id_producto DESC'); require_once __DIR__ . '/../php/encabezado.php';
?><main class="container py-5"><div class="d-flex justify-content-between align-items-center"><div><p class="eyebrow">CATÁLOGO</p><h1>Administrar productos</h1></div><a class="btn btn-principal" href="agregar_producto.php">Agregar producto</a></div><?php mostrarMensaje(); ?><div class="table-responsive mt-4"><table class="table table-hover align-middle"><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th></th></tr></thead><tbody><?php while($p=$productos->fetch_assoc()): ?><tr><td><strong><?php echo e($p['nombre_producto']); ?></strong><br><small><?php echo e($p['descripcion']); ?></small></td><td><?php echo e($p['nombre_categoria']); ?></td><td>$<?php echo number_format($p['precio'],2); ?></td><td><?php echo $p['cantidad']; ?></td><td><a class="btn btn-sm btn-outline-secondary" href="editar_producto.php?id=<?php echo $p['id_producto']; ?>">Editar</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('¿Eliminar este producto?')" href="productos.php?eliminar=<?php echo $p['id_producto']; ?>">Eliminar</a></td></tr><?php endwhile; ?></tbody></table></div></main><?php require_once __DIR__ . '/../php/pie.php'; ?>
